          "id": "code-ml-27-2-ch27_2_sklearn",
          "title": "Simulasi Pool-Based Active Learning Loop: Random vs Margin vs Entropy vs Query-by-Committee (JSD)",
          "language": "python",
          "filename": "27_2_active_learning_loop_comparison.py",
          "code": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.ensemble import BaggingClassifier\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import f1_score, roc_auc_score\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.preprocessing import StandardScaler\n\n# Dataset multikelas 3-kelas (N=1.300): Pool tak berlabel = 900, Holdout evaluasi = 400\nX, y = make_classification(\n    n_samples=1300,\n    n_features=12,\n    n_informative=8,\n    n_redundant=2,\n    n_classes=3,\n    n_clusters_per_class=1,\n    class_sep=1.55,\n    flip_y=0.02,\n    random_state=2723,\n)\nX_pool_raw, X_test_raw, y_pool, y_test = train_test_split(\n    X, y, test_size=400, stratify=y, random_state=42\n)\nscaler = StandardScaler().fit(X_pool_raw)\nX_pool = scaler.transform(X_pool_raw)\nX_test = scaler.transform(X_test_raw)\n\n# Seed awal identik: 6 sampel per kelas (18 sampel awal)\nrng_init = np.random.default_rng(100)\nseed_idx = np.concatenate([rng_init.choice(np.where(y_pool == c)[0], size=6, replace=False) for c in range(3)])\n\ndef run_active_learning(strategy: str, n_rounds: int = 10, batch_size: int = 12) -> list[tuple[int, float, float]]:\n    rng = np.random.default_rng(2724)\n    labeled = list(seed_idx)\n    unlabeled = [i for i in range(len(X_pool)) if i not in set(labeled)]\n    history = []\n\n    for r_step in range(n_rounds + 1):\n        clf = LogisticRegression(C=1.0, max_iter=400).fit(X_pool[labeled], y_pool[labeled])\n        p_te = clf.predict_proba(X_test)\n        macro_f1 = f1_score(y_test, np.argmax(p_te, axis=1), average=\"macro\")\n        auc_ovr = roc_auc_score(y_test, p_te, multi_class=\"ovr\")\n        history.append((len(labeled), macro_f1, auc_ovr))\n        if r_step == n_rounds:\n            break\n\n        X_u = X_pool[unlabeled]\n        if strategy == \"random\":\n            chosen_pos = rng.choice(len(unlabeled), size=batch_size, replace=False)\n        elif strategy == \"margin\":\n            probs = clf.predict_proba(X_u)\n            part = np.sort(probs, axis=1)\n            margins = part[:, -1] - part[:, -2]  # Makin kecil -> makin ragu antar 2 kelas teratas\n            chosen_pos = np.argsort(margins)[:batch_size]\n        elif strategy == \"entropy\":\n            probs = np.clip(clf.predict_proba(X_u), 1e-12, 1.0)\n            ent = -np.sum(probs * np.log(probs), axis=1)\n            chosen_pos = np.argsort(ent)[::-1][:batch_size]\n        elif strategy == \"qbc\":\n            # Query-by-Committee: 7 anggota bootstrap + skor disagreement Jensen-Shannon Divergence\n            comm = BaggingClassifier(\n                estimator=LogisticRegression(C=1.0, max_iter=400),\n                n_estimators=7,\n                random_state=42 + r_step,\n            ).fit(X_pool[labeled], y_pool[labeled])\n            member_probs = np.array([est.predict_proba(X_u) for est in comm.estimators_])\n            member_probs = np.clip(member_probs, 1e-12, 1.0)\n            mean_p = member_probs.mean(axis=0)\n            h_mean = -np.sum(mean_p * np.log(mean_p), axis=1)\n            mean_h = np.mean(-np.sum(member_probs * np.log(member_probs), axis=2), axis=0)\n            jsd = h_mean - mean_h\n            chosen_pos = np.argsort(jsd)[::-1][:batch_size]\n        else:\n            raise ValueError(strategy)\n\n        chosen_set = set(int(p) for p in chosen_pos)\n        for pos in sorted(chosen_set):\n            labeled.append(unlabeled[pos])\n        unlabeled = [idx for p, idx in enumerate(unlabeled) if p not in chosen_set]\n    return history\n\n# Batas atas penuh (seluruh 900 label pool)\nclf_full = LogisticRegression(C=1.0, max_iter=400).fit(X_pool, y_pool)\nf1_full = f1_score(y_test, clf_full.predict(X_test), average=\"macro\")\n\nprint(f\"=== Pool-Based Active Learning (3 Kelas, Seed=18, 10 Putaran x 12 = 138 Label vs Full 900 -> F1={f1_full:.4f}) ===\")\nfor strat in (\"random\", \"margin\", \"entropy\", \"qbc\"):\n    hist = run_active_learning(strat)\n    # Cek pada putaran ke-4 (66 label), ke-7 (102 label), dan ke-10 (138 label)\n    print(\n        f\"{strat.upper():8s} | @18={hist[0][1]:.4f} | @66={hist[4][1]:.4f} \"\n        f\"| @102={hist[7][1]:.4f} | @138={hist[10][1]:.4f} (AUC={hist[10][2]:.4f})\"\n    )",
          "expectedOutput": "=== Pool-Based Active Learning (3 Kelas, Seed=18, 10 Putaran x 12 = 138 Label vs Full 900 -> F1=0.9164) ===\nRANDOM   | @18=0.8200 | @66=0.8839 | @102=0.8734 | @138=0.8917 (AUC=0.9694)\nMARGIN   | @18=0.8200 | @66=0.9220 | @102=0.9195 | @138=0.9141 (AUC=0.9803)\nENTROPY  | @18=0.8200 | @66=0.8823 | @102=0.8939 | @138=0.9110 (AUC=0.9808)\nQBC      | @18=0.8200 | @66=0.8547 | @102=0.8884 | @138=0.9012 (AUC=0.9781)",
          "actualOutput": "=== Pool-Based Active Learning (3 Kelas, Seed=18, 10 Putaran x 12 = 138 Label vs Full 900 -> F1=0.9164) ===\nRANDOM   | @18=0.8200 | @66=0.8839 | @102=0.8734 | @138=0.8917 (AUC=0.9694)\nMARGIN   | @18=0.8200 | @66=0.9220 | @102=0.9195 | @138=0.9141 (AUC=0.9803)\nENTROPY  | @18=0.8200 | @66=0.8823 | @102=0.8939 | @138=0.9110 (AUC=0.9808)\nQBC      | @18=0.8200 | @66=0.8547 | @102=0.8884 | @138=0.9012 (AUC=0.9781)",
          "explanation": "Mensimulasikan 10 putaran Pool-Based Active Learning (18 -> 138 label) pada klasifikasi 3-kelas membandingkan Random, Margin, Entropy, dan QBC (Bagging 7 anggota + JSD) terhadap batas atas 900 label penuh.",
