          "id": "code-ml-27-2-ch27_2_diag",
          "title": "Production Audit: Keruntuhan Kalibrasi akibat Klon LF Berkorelasi & Redundansi Batch vs K-Means Diversity",
          "language": "python",
          "filename": "27_2_lf_correlation_and_batch_diversity_audit.py",
          "code": "import numpy as np\nfrom sklearn.cluster import KMeans\nfrom sklearn.metrics import brier_score_loss\n\nrng = np.random.default_rng(2725)\n\n# -----------------------------------------------------------------------------\n# Audit 1: Bahaya Duplikasi / Korelasi Tinggi antar Labeling Functions pada Naive EM\n# -----------------------------------------------------------------------------\nN = 1000\ny_true = (rng.uniform(size=N) < 0.35).astype(int)\n\n# 3 LF independen berakurasi baik (0.82) vs 1 LF lemah (0.62) yang DIKLONING 5 KALI (korelasi=0.95!)\ndef make_lf(acc: float) -> np.ndarray:\n    corr = rng.uniform(size=N) < acc\n    return np.where(corr, y_true, 1 - y_true)\n\nlf_good_1, lf_good_2, lf_good_3 = make_lf(0.84), make_lf(0.82), make_lf(0.80)\nlf_weak_base = make_lf(0.58)\n# 5 klon sangat berkorelasi dari lf_weak_base (hanya 4% beda acak -> rho ~ 0.92!)\nlf_clones = [np.where(rng.uniform(size=N) < 0.96, lf_weak_base, 1 - lf_weak_base) for _ in range(5)]\n\nL_corrupt = np.column_stack([lf_good_1, lf_good_2, lf_good_3] + lf_clones)\n\n# Deteksi otomatis klon LF lewat matriks kesepakatan berpasangan (pairwise agreement)\nm = L_corrupt.shape[1]\nagree_mat = np.array([[np.mean(L_corrupt[:, i] == L_corrupt[:, j]) for j in range(m)] for i in range(m)])\n# Deduplikasi greedy: buang LF jika kesepakatan dengan LF sebelumnya > 0.88\nkept_cols = []\nfor j in range(m):\n    if all(agree_mat[j, k] <= 0.88 for k in kept_cols):\n        kept_cols.append(j)\n\ndef simple_em_prob(L: np.ndarray) -> np.ndarray:\n    pi = 0.5\n    a = np.full(L.shape[1], 0.75)\n    for _ in range(30):\n        lp1 = np.full(len(L), np.log(pi))\n        lp0 = np.full(len(L), np.log(1 - pi))\n        for j in range(L.shape[1]):\n            aj = np.clip(a[j], 1e-4, 1 - 1e-4)\n            lp1 += np.where(L[:, j] == 1, np.log(aj), np.log(1 - aj))\n            lp0 += np.where(L[:, j] == 1, np.log(1 - aj), np.log(aj))\n        mx = np.maximum(lp1, lp0)\n        g = np.exp(lp1 - mx) / (np.exp(lp1 - mx) + np.exp(lp0 - mx))\n        pi = float(np.clip(g.mean(), 0.05, 0.95))\n        for j in range(L.shape[1]):\n            a[j] = float(np.clip(np.mean(np.where(L[:, j] == 1, g, 1 - g)), 0.05, 0.95))\n    return g\n\np_naive = simple_em_prob(L_corrupt)\np_dedup = simple_em_prob(L_corrupt[:, kept_cols])\n\nprint(\"=== Audit 1: Bahaya Korelasi LF (5 Klon Lemah Merusak Kalibrasi Naive EM!) ===\")\nprint(f\"LF dipertahankan pasca-filter korelasi (>0.88): indeks {kept_cols} (membuang {m - len(kept_cols)} klon!)\")\nprint(f\"Naive EM (8 LF dg 5 klon)  -> Acc={np.mean((p_naive>=0.5)==y_true):.4f} | Brier={brier_score_loss(y_true, p_naive):.4f}\")\nprint(f\"Dedup EM (4 LF independen) -> Acc={np.mean((p_dedup>=0.5)==y_true):.4f} | Brier={brier_score_loss(y_true, p_dedup):.4f}\")\n\n# -----------------------------------------------------------------------------\n# Audit 2: Redundansi Batch Active Learning (Top-B Margin vs Diversity K-Means)\n# -----------------------------------------------------------------------------\n# 60 kandidat paling tak pasti di ruang fitur 2D: 45 terkumpul rapat di 1 klaster sempit, 15 di 3 wilayah lain\nc1 = rng.normal([0.0, 0.0], 0.05, size=(45, 2))\nc2 = rng.normal([3.0, 0.0], 0.15, size=(5, 2))\nc3 = rng.normal([0.0, 3.0], 0.15, size=(5, 2))\nc4 = rng.normal([3.0, 3.0], 0.15, size=(5, 2))\nX_cand = np.vstack([c1, c2, c3, c4])\n# Semua 45 titik klaster-1 punya margin sangat tipis (0.01..0.05), wilayah lain 0.06..0.10\nmargins_cand = np.concatenate([rng.uniform(0.01, 0.05, 45), rng.uniform(0.06, 0.10, 15)])\n\nB = 8\nnaive_top_b = np.argsort(margins_cand)[:B]\n# Diversity-aware batch: klasterkan 60 kandidat menjadi B klaster, pilih 1 titik paling dekat pusat per klaster\nkm = KMeans(n_clusters=B, n_init=10, random_state=42).fit(X_cand)\ndiv_batch = []\nfor cid in range(B):\n    members = np.where(km.labels_ == cid)[0]\n    dists = np.linalg.norm(X_cand[members] - km.cluster_centers_[cid], axis=1)\n    div_batch.append(int(members[np.argmin(dists)]))\n\ndef mean_pairwise_dist(pts: np.ndarray) -> float:\n    d = np.linalg.norm(pts[:, None, :] - pts[None, :, :], axis=-1)\n    iu = np.triu_indices(len(pts), k=1)\n    return float(d[iu].mean())\n\nprint(\"\\n=== Audit 2: Keragaman Batch Active Learning (B=8 dari 60 Kandidat Tak Pasti) ===\")\nprint(f\"Naive Top-B Margin         -> Jarak rata-rata antar sampel={mean_pairwise_dist(X_cand[naive_top_b]):.4f} (terjebak 1 klaster!)\")\nprint(f\"K-Means Diversity Batch    -> Jarak rata-rata antar sampel={mean_pairwise_dist(X_cand[div_batch]):.4f} (menjelajah 4 wilayah!)\")",
          "expectedOutput": "=== Audit 1: Bahaya Korelasi LF (5 Klon Lemah Merusak Kalibrasi Naive EM!) ===\nLF dipertahankan pasca-filter korelasi (>0.88): indeks [0, 1, 2, 3] (membuang 4 klon!)\nNaive EM (8 LF dg 5 klon)  -> Acc=0.5890 | Brier=0.4103\nDedup EM (4 LF independen) -> Acc=0.9060 | Brier=0.0713\n\n=== Audit 2: Keragaman Batch Active Learning (B=8 dari 60 Kandidat Tak Pasti) ===\nNaive Top-B Margin         -> Jarak rata-rata antar sampel=0.0924 (terjebak 1 klaster!)\nK-Means Diversity Batch    -> Jarak rata-rata antar sampel=2.8589 (menjelajah 4 wilayah!)",
