          "language": "python",
          "filename": "27_3_data_contract_engine_scratch.py",
          "code": "from dataclasses import dataclass, field\nimport numpy as np\nimport pandas as pd\n\n@dataclass\nclass ColumnRule:\n    dtype_kind: str            # \"float\", \"int\", \"str\"\n    nullable: bool = False\n    max_null_rate: float = 0.05\n    min_val: float | None = None\n    max_val: float | None = None\n    allowed: set[str] | None = None\n\n@dataclass\nclass DataContractEngine:\n    contract_version: str\n    columns: dict[str, ColumnRule]\n    max_quarantine_rate: float = 0.15\n    cross_checks: list = field(default_factory=list)\n\n    def validate_and_route(self, df: pd.DataFrame) -> dict:\n        schema_errors: list[str] = []\n        # 1) Cek keberadaan kolom wajib (Structural Contract)\n        missing_cols = [c for c in self.columns if c not in df.columns]\n        if missing_cols:\n            return {\n                \"decision\": \"CIRCUIT_BREAK_SCHEMA\",\n                \"clean_rows\": 0,\n                \"quarantined_rows\": len(df),\n                \"schema_errors\": [f\"MISSING_COLUMNS:{missing_cols}\"],\n                \"reason_counts\": {},\n            }\n\n        n = len(df)\n        bad_mask = np.zeros(n, dtype=bool)\n        reasons = [[] for _ in range(n)]\n        batch_alerts: list[str] = []\n\n        # 2) Cek kontrak per kolom (Row-Level Domain + Statistical Null Ceiling)\n        for col, rule in self.columns.items():\n            s = df[col]\n            null_mask = s.isna().to_numpy()\n            null_rate = float(null_mask.mean())\n            if null_rate > rule.max_null_rate:\n                batch_alerts.append(f\"NULL_SPIKE:{col}({100*null_rate:.1f}%>{100*rule.max_null_rate:.1f}%)\")\n            if not rule.nullable and null_mask.any():\n                for idx in np.where(null_mask)[0]:\n                    bad_mask[idx] = True\n                    reasons[idx].append(f\"NULL:{col}\")\n\n            if rule.dtype_kind in (\"float\", \"int\"):\n                vals = pd.to_numeric(s, errors=\"coerce\").to_numpy(dtype=float)\n                non_finite = (~null_mask) & (~np.isfinite(vals))\n                if non_finite.any():\n                    for idx in np.where(non_finite)[0]:\n                        bad_mask[idx] = True\n                        reasons[idx].append(f\"NON_FINITE:{col}\")\n                valid_num = (~null_mask) & np.isfinite(vals)\n                if rule.min_val is not None:\n                    lo_bad = valid_num & (vals < rule.min_val)\n                    for idx in np.where(lo_bad)[0]:\n                        bad_mask[idx] = True\n                        reasons[idx].append(f\"BELOW_MIN:{col}\")\n                if rule.max_val is not None:\n                    hi_bad = valid_num & (vals > rule.max_val)\n                    for idx in np.where(hi_bad)[0]:\n                        bad_mask[idx] = True\n                        reasons[idx].append(f\"ABOVE_MAX:{col}\")\n            elif rule.dtype_kind == \"str\" and rule.allowed is not None:\n                str_vals = s.astype(str).to_numpy()\n                unseen = (~null_mask) & (~np.isin(str_vals, list(rule.allowed)))\n                for idx in np.where(unseen)[0]:\n                    bad_mask[idx] = True\n                    reasons[idx].append(f\"INVALID_ENUM:{col}\")\n\n        # 3) Cek Invarian Lintas-Kolom (Cross-Column Semantic Contract)\n        for check_name, check_fn in self.cross_checks:\n            ok_arr = np.asarray(check_fn(df), dtype=bool)\n            for idx in np.where(~ok_arr)[0]:\n                bad_mask[idx] = True\n                reasons[idx].append(f\"CROSS_FAIL:{check_name}\")\n\n        q_rate = float(bad_mask.mean())\n        reason_counts: dict[str, int] = {}\n        for r_list in reasons:\n            for tag in r_list:\n                reason_counts[tag] = reason_counts.get(tag, 0) + 1\n\n        if q_rate > self.max_quarantine_rate or len(batch_alerts) > 0:\n            decision = \"CIRCUIT_BREAK_DLQ\"\n        elif bad_mask.any():\n            decision = \"PARTIAL_QUARANTINE_SERVE\"\n        else:\n            decision = \"PASS_CLEAN\"\n\n        return {\n            \"decision\": decision,\n            \"clean_rows\": int((~bad_mask).sum()),\n            \"quarantined_rows\": int(bad_mask.sum()),\n            \"quarantine_rate\": round(q_rate, 4),\n            \"batch_alerts\": batch_alerts,\n            \"reason_counts\": reason_counts,\n        }\n\ncontract = DataContractEngine(\n    contract_version=\"bnpl_income_v2.1.0\",\n    columns={\n        \"monthly_income_idr\": ColumnRule(\"float\", nullable=False, max_null_rate=0.02, min_val=500_000.0, max_val=500_000_000.0),\n        \"loan_amount_idr\": ColumnRule(\"float\", nullable=False, max_null_rate=0.0, min_val=100_000.0, max_val=100_000_000.0),\n        \"discount_idr\": ColumnRule(\"float\", nullable=False, max_null_rate=0.0, min_val=0.0, max_val=50_000_000.0),\n        \"country_iso\": ColumnRule(\"str\", nullable=False, max_null_rate=0.0, allowed={\"ID\", \"SG\", \"MY\"}),\n    },\n    max_quarantine_rate=0.15,\n    cross_checks=[\n        (\"discount_le_loan\", lambda d: d[\"discount_idr\"].fillna(0) <= d[\"loan_amount_idr\"].fillna(0)),\n    ],\n)\n\nbatch_healthy = pd.DataFrame({\n    \"monthly_income_idr\": [8_500_000.0, 12_000_000.0, 6_200_000.0, 15_400_000.0, 9_100_000.0, 7_800_000.0, 11_000_000.0, 5_500_000.0],\n    \"loan_amount_idr\": [1_500_000.0, 3_000_000.0, 800_000.0, 4_200_000.0, 1_200_000.0, 900_000.0, 2_000_000.0, 600_000.0],\n    \"discount_idr\": [50_000.0, 100_000.0, 0.0, 200_000.0, 25_000.0, 0.0, 50_000.0, 10_000.0],\n    \"country_iso\": [\"ID\", \"ID\", \"MY\", \"SG\", \"ID\", \"ID\", \"MY\", \"ID\"],\n})\n\nbatch_minor_corrupt = batch_healthy.copy()\nbatch_minor_corrupt.loc[7, \"discount_idr\"] = 999_000.0  # 1 baris melanggar discount <= loan (12.5% <= 15%)\n\nbatch_unit_bug = batch_healthy.copy()\nbatch_unit_bug[\"monthly_income_idr\"] = batch_unit_bug[\"monthly_income_idr\"] / 1000.0  # Bug hulu: Rp -> ribu Rp!\n\nprint(\"=== Declarative Data Contract Engine (Pandera Pattern + DLQ Quarantine) ===\")\nfor label, df_in in [(\"Batch Sehat\", batch_healthy), (\"1 Baris Cross-Fail\", batch_minor_corrupt), (\"Bug Satuan 1/1000x\", batch_unit_bug)]:\n    res = contract.validate_and_route(df_in)\n    print(f\"{label:20s} -> {res['decision']:24s} | clean={res['clean_rows']}/8 | dlq={res['quarantined_rows']}/8 | reasons={res['reason_counts']}\")",
          "expectedOutput": "=== Declarative Data Contract Engine (Pandera Pattern + DLQ Quarantine) ===\nBatch Sehat          -> PASS_CLEAN               | clean=8/8 | dlq=0/8 | reasons={}\n1 Baris Cross-Fail   -> PARTIAL_QUARANTINE_SERVE | clean=7/8 | dlq=1/8 | reasons={'CROSS_FAIL:discount_le_loan': 1}\nBug Satuan 1/1000x   -> CIRCUIT_BREAK_DLQ        | clean=0/8 | dlq=8/8 | reasons={'BELOW_MIN:monthly_income_idr': 8}",
          "actualOutput": "=== Declarative Data Contract Engine (Pandera Pattern + DLQ Quarantine) ===\nBatch Sehat          -> PASS_CLEAN               | clean=8/8 | dlq=0/8 | reasons={}\n1 Baris Cross-Fail   -> PARTIAL_QUARANTINE_SERVE | clean=7/8 | dlq=1/8 | reasons={'CROSS_FAIL:discount_le_loan': 1}\nBug Satuan 1/1000x   -> CIRCUIT_BREAK_DLQ        | clean=0/8 | dlq=8/8 | reasons={'BELOW_MIN:monthly_income_idr': 8}",
          "explanation": "Mengimplementasikan DataContractEngine deklaratif zero-dependency (Structural, Domain, Cross-Column discount <= loan, Statistical Null Ceiling) dengan pemisahan otomatis PASS_CLEAN, PARTIAL_QUARANTINE_SERVE (1 baris ke DLQ), dan CIRCUIT_BREAK_DLQ pada bug satuan 1/1000x.",
          "verificationStatus": "VERIFIED_RUNNABLE",
          "isVerifiedOutput": true,
          "runtimeBadge": "pyodide-ready",
          "level": "menengah"
