          "id": "code-ml-27-4-ch27_4_sklearn",
          "title": "Replikasi van den Goorbergh (2022) & Solusi 2026: Oversampling vs Balanced vs Native + TunedThresholdClassifierCV",
          "language": "python",
          "filename": "27_4_elkan_tuned_threshold_2026.py",
          "code": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.metrics import average_precision_score, brier_score_loss, make_scorer, roc_auc_score\nfrom sklearn.model_selection import TunedThresholdClassifierCV, train_test_split\n\n# Dataset risiko klaim curang (prevalensi = 3%, biaya FN = 25 unit, biaya FP = 1 unit)\n# Menurut Teorema Elkan (2001): ambang Bayes-optimal tau* = C_FP / (C_FP + C_FN) = 1 / 26 = 0.0385!\nC_FN, C_FP = 25.0, 1.0\ntau_elkan = C_FP / (C_FP + C_FN)\n\nX, y = make_classification(\n    n_samples=1600,\n    n_features=12,\n    n_informative=7,\n    n_redundant=2,\n    weights=[0.97, 0.03],\n    class_sep=1.55,\n    flip_y=0.005,\n    random_state=2742,\n)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.35, stratify=y, random_state=42)\n\ndef neg_business_cost(y_true_arr, y_pred_arr) -> float:\n    fn = np.sum((y_true_arr == 1) & (y_pred_arr == 0))\n    fp = np.sum((y_true_arr == 0) & (y_pred_arr == 1))\n    return -float(C_FN * fn + C_FP * fp)\n\ncost_scorer = make_scorer(neg_business_cost)\n\ndef ece_score(y_true_arr, p, n_bins=10) -> float:\n    edges = np.linspace(0.0, 1.0, n_bins + 1)\n    val = 0.0\n    for i in range(n_bins):\n        m = (p >= edges[i]) & (p <= edges[i + 1] if i == n_bins - 1 else p < edges[i + 1])\n        if m.any():\n            val += float(m.mean()) * abs(float(y_true_arr[m].mean()) - float(p[m].mean()))\n    return val\n\n# A) RandomOverSampler 50:50 + ambang baku 0.5 (Anti-Pattern!)\nrng = np.random.default_rng(42)\nmaj_idx = np.where(y_tr == 0)[0]\nmin_idx = np.where(y_tr == 1)[0]\nover_min = rng.choice(min_idx, size=len(maj_idx), replace=True)\nX_ros = np.vstack([X_tr[maj_idx], X_tr[over_min]])\ny_ros = np.concatenate([y_tr[maj_idx], y_tr[over_min]])\ngbdt_ros = HistGradientBoostingClassifier(max_depth=3, max_iter=60, random_state=42).fit(X_ros, y_ros)\n\n# B) class_weight=\"balanced\" + ambang baku 0.5\ngbdt_bal = HistGradientBoostingClassifier(max_depth=3, max_iter=60, class_weight=\"balanced\", random_state=42).fit(X_tr, y_tr)\n\n# C) Native Distribution (tanpa SMOTE!) + TunedThresholdClassifierCV berbasis biaya asimetris (Solusi 2026!)\ngbdt_base = HistGradientBoostingClassifier(max_depth=3, max_iter=60, random_state=42)\ntuned_clf = TunedThresholdClassifierCV(\n    estimator=gbdt_base,\n    scoring=cost_scorer,\n    cv=5,\n    thresholds=80,\n    random_state=42,\n).fit(X_tr, y_tr)\n\n# D) Native Distribution + Ambang Analitis Teorema Elkan langsung\ngbdt_native = HistGradientBoostingClassifier(max_depth=3, max_iter=60, random_state=42).fit(X_tr, y_tr)\n\nprint(f\"=== Replikasi Produksi 2026: Oversampling vs Balanced vs Native + TunedThresholdClassifierCV (Elkan tau*={tau_elkan:.4f}) ===\")\nrows = [\n    (\"A. Oversampling 50:50 (t=0.50)\", gbdt_ros.predict_proba(X_te)[:, 1], gbdt_ros.predict(X_te)),\n    (\"B. class_weight='bal' (t=0.50)\", gbdt_bal.predict_proba(X_te)[:, 1], gbdt_bal.predict(X_te)),\n    (f\"C. Native+TunedCV (t={tuned_clf.best_threshold_:.4f})\", tuned_clf.predict_proba(X_te)[:, 1], tuned_clf.predict(X_te)),\n    (f\"D. Native+Elkan   (t={tau_elkan:.4f})\", gbdt_native.predict_proba(X_te)[:, 1], (gbdt_native.predict_proba(X_te)[:, 1] >= tau_elkan).astype(int)),\n]\nfor label, prob, pred in rows:\n    cost = -neg_business_cost(y_te, pred)\n    print(\n        f\"{label:31s} | AUC={roc_auc_score(y_te, prob):.4f} | PR-AUC={average_precision_score(y_te, prob):.4f} \"\n        f\"| Brier={brier_score_loss(y_te, prob):.4f} | ECE={ece_score(y_te, prob):.4f} | Cost={cost:6.0f}\"\n    )",
          "expectedOutput": "=== Replikasi Produksi 2026: Oversampling vs Balanced vs Native + TunedThresholdClassifierCV (Elkan tau*=0.0385) ===\nA. Oversampling 50:50 (t=0.50)  | AUC=0.9486 | PR-AUC=0.8895 | Brier=0.0174 | ECE=0.0322 | Cost=    62\nB. class_weight='bal' (t=0.50)  | AUC=0.9448 | PR-AUC=0.8980 | Brier=0.0200 | ECE=0.0415 | Cost=    38\nC. Native+TunedCV (t=0.0375)    | AUC=0.9504 | PR-AUC=0.9202 | Brier=0.0065 | ECE=0.0096 | Cost=    43\nD. Native+Elkan   (t=0.0385)    | AUC=0.9504 | PR-AUC=0.9202 | Brier=0.0065 | ECE=0.0096 | Cost=    43",
          "actualOutput": "=== Replikasi Produksi 2026: Oversampling vs Balanced vs Native + TunedThresholdClassifierCV (Elkan tau*=0.0385) ===\nA. Oversampling 50:50 (t=0.50)  | AUC=0.9486 | PR-AUC=0.8895 | Brier=0.0174 | ECE=0.0322 | Cost=    62\nB. class_weight='bal' (t=0.50)  | AUC=0.9448 | PR-AUC=0.8980 | Brier=0.0200 | ECE=0.0415 | Cost=    38\nC. Native+TunedCV (t=0.0375)    | AUC=0.9504 | PR-AUC=0.9202 | Brier=0.0065 | ECE=0.0096 | Cost=    43\nD. Native+Elkan   (t=0.0385)    | AUC=0.9504 | PR-AUC=0.9202 | Brier=0.0065 | ECE=0.0096 | Cost=    43",
