          "code": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.metrics import average_precision_score, brier_score_loss, f1_score\nfrom sklearn.model_selection import StratifiedKFold, train_test_split\n\nrng = np.random.default_rng(2743)\n\n# Bangkitkan data imbalanced (pi = 3%): pisahkan Prod Holdout (30%) sejak detik ke-0!\nX_all, y_all = make_classification(\n    n_samples=1500,\n    n_features=12,\n    n_informative=5,\n    n_redundant=2,\n    weights=[0.97, 0.03],\n    class_sep=1.25,\n    flip_y=0.01,\n    random_state=2743,\n)\nX_dev, X_prod, y_dev, y_prod = train_test_split(X_all, y_all, test_size=0.30, stratify=y_all, random_state=42)\n\ndef smote_simple(X_in: np.ndarray, y_in: np.ndarray, k: int = 5, seed: int = 42) -> tuple[np.ndarray, np.ndarray]:\n    r = np.random.default_rng(seed)\n    Xm = X_in[y_in == 1]\n    n_syn = int(np.sum(y_in == 0)) - len(Xm)\n    d = np.linalg.norm(Xm[:, None, :] - Xm[None, :, :], axis=-1)\n    np.fill_diagonal(d, np.inf)\n    nn = np.argsort(d, axis=1)[:, : min(k, len(Xm) - 1)]\n    bi = r.integers(0, len(Xm), size=n_syn)\n    ni = nn[bi, r.integers(0, nn.shape[1], size=n_syn)]\n    X_syn = Xm[bi] + r.uniform(0.0, 1.0, size=(n_syn, 1)) * (Xm[ni] - Xm[bi])\n    return np.vstack([X_in, X_syn]), np.concatenate([y_in, np.ones(n_syn, dtype=int)])\n\ndef make_gbdt() -> HistGradientBoostingClassifier:\n    return HistGradientBoostingClassifier(max_depth=3, max_iter=50, random_state=42)\n\n# 1) BENCANA KLASIK: SMOTE pada seluruh X_dev SEBELUM 5-Fold StratifiedKFold!\nX_leaky_sm, y_leaky_sm = smote_simple(X_dev, y_dev, seed=42)\nskf = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)\nleaky_f1s, leaky_prs = [], []\nfor tr_i, va_i in skf.split(X_leaky_sm, y_leaky_sm):\n    m = make_gbdt().fit(X_leaky_sm[tr_i], y_leaky_sm[tr_i])\n    pv = m.predict_proba(X_leaky_sm[va_i])[:, 1]\n    leaky_f1s.append(f1_score(y_leaky_sm[va_i], (pv >= 0.5).astype(int)))\n    leaky_prs.append(average_precision_score(y_leaky_sm[va_i], pv))\n\n# Evaluasi jujur model hasil SMOTE pada X_prod yang tak pernah disentuh SMOTE\nm_smote_full = make_gbdt().fit(X_leaky_sm, y_leaky_sm)\np_prod_sm = m_smote_full.predict_proba(X_prod)[:, 1]\n\n# 2) EVALUASI BERSIH: SMOTE hanya DI DALAM lipatan latih vs Native tanpa SMOTE!\nclean_sm_f1s, clean_sm_prs, clean_sm_briers = [], [], []\nnative_prs, native_briers = [], []\nfor tr_i, va_i in skf.split(X_dev, y_dev):\n    Xs_f, ys_f = smote_simple(X_dev[tr_i], y_dev[tr_i], seed=42)\n    ms = make_gbdt().fit(Xs_f, ys_f)\n    pvs = ms.predict_proba(X_dev[va_i])[:, 1]\n    clean_sm_f1s.append(f1_score(y_dev[va_i], (pvs >= 0.5).astype(int)))\n    clean_sm_prs.append(average_precision_score(y_dev[va_i], pvs))\n    clean_sm_briers.append(brier_score_loss(y_dev[va_i], pvs))\n\n    mn = make_gbdt().fit(X_dev[tr_i], y_dev[tr_i])\n    pvn = mn.predict_proba(X_dev[va_i])[:, 1]\n    native_prs.append(average_precision_score(y_dev[va_i], pvn))\n    native_briers.append(brier_score_loss(y_dev[va_i], pvn))\n\nm_native_full = make_gbdt().fit(X_dev, y_dev)\np_prod_nat = m_native_full.predict_proba(X_prod)[:, 1]\n\nprint(\"=== Audit Kebocoran Fatal: SMOTE Sebelum CV Split vs Di Dalam CV vs Native (HistGBDT) ===\")\nprint(f\"[BUG] SMOTE SEBELUM CV Split (Ilusi!) : CV F1={np.mean(leaky_f1s):.4f} | CV PR-AUC={np.mean(leaky_prs):.4f}  <-- PALSU!\")\nprint(f\"[REAL] Model SMOTE pd Prod Holdout    : PR-AUC={average_precision_score(y_prod, p_prod_sm):.4f} | Brier={brier_score_loss(y_prod, p_prod_sm):.4f} | MeanP={p_prod_sm.mean():.4f} (asli={y_prod.mean():.4f})\")\nprint(f\"[OK-CV] SMOTE DI DALAM Fold           : CV F1={np.mean(clean_sm_f1s):.4f} | CV PR-AUC={np.mean(clean_sm_prs):.4f} | CV Brier={np.mean(clean_sm_briers):.4f}\")\nprint(f\"[2026] Native Tanpa SMOTE (CV / Prod) : CV PR-AUC={np.mean(native_prs):.4f} | Prod PR-AUC={average_precision_score(y_prod, p_prod_nat):.4f} | Prod Brier={brier_score_loss(y_prod, p_prod_nat):.4f} | MeanP={p_prod_nat.mean():.4f}\")",
